mapper.update:
UPDATE tbl_user_club_attendance
SET checkout_time = #{checkoutTime}
WHERE id = (
    SELECT id FROM (
                       SELECT id
                       FROM tbl_user_club_attendance
                       WHERE user_id = #{userId}
                         AND club_id = #{clubId}
                         AND checkout_time IS NULL
                         AND is_deleted = 0
                       ORDER BY checkin_time DESC
                           LIMIT 1
                   ) AS temp
)

mapper.select:
SELECT user_id, SUM( TIMESTAMPDIFF( SECOND, checkin_time, checkout_time ) ) AS attendance_duration_time FROM tbl_user_club_attendance WHERE is_deleted = 0 AND club_id = #{clubId}
AND user_id LIKE CONCAT('%', #{getAttendanceTimeReq.userId}, '%')
AND checkin_time BETWEEN #{getAttendanceTimeReq.startTime} AND #{getAttendanceTimeReq.endTime}
AND checkout_time IS NOT NULL GROUP BY user_id;

SELECT user_id, SUM( TIMESTAMPDIFF( SECOND, checkin_time, checkout_time ) ) AS attendance_duration_time FROM tbl_user_club_attendance WHERE is_deleted = 0 AND club_id = #{clubId}
AND user_id LIKE CONCAT('%', #{getAttendanceTimeReq.userId}, '%')
AND user_id IN
#{userId}
